  let xr = right >>> 0;
  for (let i = 0; i < BLOWFISH_ROUNDS; i++) {
    xl = bfU32(xl ^ ctx.pbox[i]);
    xr = bfU32(bfF(ctx, xl) ^ xr);
    const tmp = xl;
    xl = xr;
    xr = tmp;
  }
  const tmp = xl;
  xl = xr;
  xr = tmp;
  xr = bfU32(xr ^ ctx.pbox[BLOWFISH_ROUNDS]);
  xl = bfU32(xl ^ ctx.pbox[BLOWFISH_ROUNDS + 1]);
